import Foundation

public enum ToolCatalog {
    public static let names = ["kslides_status", "kslides_list_lessons", "kslides_get_lesson", "kslides_create_lesson", "kslides_update_lesson", "kslides_upsert_slide", "kslides_reorder_slides", "kslides_attach_artwork", "kslides_image_brief", "kslides_import_plan", "kslides_export", "kslides_design_catalog", "kslides_review_lesson", "kslides_geometry_engines", "kslides_render_scene", "kslides_render_job", "kslides_cancel_render", "kslides_apply_scene", "kslides_geometry_texture"]
    public static func tools() -> [[String: Any]] {
        func str(_ desc: String) -> [String: Any] { ["type":"string", "description":desc] }
        let lid = str("Lesson UUID returned by create/list.")
        let rev: [String: Any] = ["type":"integer", "minimum":1, "description":"Current revision. Stale writes are rejected; re-read before retrying."]
        func tool(_ name: String, _ description: String, _ properties: [String: Any] = [:], _ required: [String] = [], read: Bool = false) -> [String: Any] {
            ["name":name, "description":description, "inputSchema":["type":"object", "properties":properties, "required":required, "additionalProperties":false], "annotations":["readOnlyHint":read,"destructiveHint":false,"idempotentHint":read,"openWorldHint":false]]
        }
        return [
            tool(names[0], "Read the running KSlides app version, connection status, and supported tools.", read:true),
            tool(names[1], "List saved lessons and their revisions.", read:true),
            tool(names[2], "Read a full lesson, slides, teacher notes and current revision.", ["lesson_id":lid], ["lesson_id"], read:true),
            tool(names[3], "Create and save a new educator lesson. Generates no AI content automatically.", ["title":str("Lesson title"),"topic":str("Teaching topic"),"audience":str("Age/year/language level"),"goals":str("Measurable goals"),"source_content":str("Source lesson material"),"world":["type":"string","enum":World.allCases.map(\.rawValue)]], ["title","topic","audience"]),
            tool(names[4], "Update lesson metadata or theme with optimistic revision protection.", ["lesson_id":lid,"expected_revision":rev,"title":str("Title"),"topic":str("Topic"),"audience":str("Audience"),"goals":str("Goals"),"source_content":str("Source content"),"world":["type":"string","enum":World.allCases.map(\.rawValue)]], ["lesson_id","expected_revision"]),
            tool(names[5], "Add a slide or update an existing slide. Native layouts keep text editable. Illustrated mode uses source text to generate a complete image; changing words requires regenerated artwork. Teacher notes stay private in presentation.", ["lesson_id":lid,"expected_revision":rev,"slide_id":str("Existing slide UUID; omit to append."),"title":str("Exact title"),"body":str("Exact visible body text, newline-separated"),"phase":str("Teaching phase"),"purpose":str("One teaching purpose"),"student_action":str("Learner action"),"teacher_notes":str("Private cues/answers"),"image_prompt":str("Art direction and consistency locks. Illustrated mode includes exact student lettering; native layouts use unlettered supporting artwork."),"duration_seconds":["type":"integer","minimum":1,"maximum":3600],"layout":["type":"string","enum":SlideLayout.allCases.map(\.rawValue)],"typography":["type":"string","description":"Use theme to restore the world default, or choose a named type style.","enum":["theme"]+TypeStyle.allCases.map(\.rawValue)],"reveal_for":str("Earlier question slide UUID, if this slide reveals its answer")], ["lesson_id","expected_revision","title"]),
            tool(names[6], "Reorder all slides using each slide UUID exactly once; validates reveal order.", ["lesson_id":lid,"expected_revision":rev,"slide_ids":["type":"array","items":["type":"string"]]], ["lesson_id","expected_revision","slide_ids"]),
            tool(names[7], "Attach actual PNG/JPEG artwork to a slide. Prefer image_base64 for sandbox-safe transfer; provide one image source. Existing art remains preserved as a managed asset.", ["lesson_id":lid,"slide_id":str("Slide UUID"),"expected_revision":rev,"image_base64":str("Base64 PNG/JPEG bytes, up to 15 MB decoded"),"image_path":str("Absolute local path when accessible to the app"),"provenance":str("Image tool/provider and generation prompt/reference notes")], ["lesson_id","slide_id","expected_revision","provenance"]),
            tool(names[8], "Read the compiled artwork prompt and exact overlay text. Use your image generator, then attach the result; this tool itself does not render images.", ["lesson_id":lid,"slide_id":str("Slide UUID")], ["lesson_id","slide_id"], read:true),
            tool(names[9], "Import the earlier Lesson World system-pack JSON plan as a new saved KSlides lesson. Pass the plan as an object.", ["plan":["type":"object"]], ["plan"]),
            tool(names[10], "Export a saved lesson as PPTX, PDF, PNG slide images, printable worksheet PDF, or source JSON. Output stays in managed Exports; returns actual paths. PPTX includes editable native text and private speaker notes. Illustrated-mode slides are full-slide images with lettering baked in.", ["lesson_id":lid,"format":["type":"string","enum":["pptx","pdf","png","worksheet","json"]]], ["lesson_id","format"]),
            tool(names[11], "Read composition contracts, type styles, and visual worlds before designing varied educator slides.",read:true),
            tool(names[12], "Review a saved lesson for text fit, layout repetition, missing artwork, and reveal links. Reports warnings; does not assess factual or curriculum correctness.",["lesson_id":lid],["lesson_id"],read:true),
            tool(names[13], "Inspect the connected local geometry worker and supported shapes. No model downloads required.",read:true),
            tool(names[14], "Queue a local NumPy/Blender mathematical scene. Returns a job immediately. Appends a geometry slide, or replaces slide_id, after verified rendering at the captured revision. Keep the MCP connection open. Native labels and formulas remain editable.",["lesson_id":lid,"expected_revision":rev,"slide_id":str("Existing slide UUID; omit to append a new scene."),"title":str("Student-facing title; defaults to shape name."),"scene":["type":"object","properties":["kind":["type":"string","enum":GeometryKind.allCases.map(\.rawValue)],"size":["type":"number","minimum":0.05,"maximum":1000,"description":"Radius for circle/sphere; side length for square/cube."],"yaw":["type":"number","minimum":-180,"maximum":180],"pitch":["type":"number","minimum":-80,"maximum":80],"unit":str("Short unit such as cm or units"),"texture":str("Managed artwork filename from a lesson or Geometry Lab; omit for default material.")],"required":["kind","size"],"additionalProperties":false]],["lesson_id","expected_revision","scene"]),
            tool(names[15], "Inspect a render job, state, scene parameters and target lesson. Ready means the result is preserved and awaits revision-safe application.",["job_id":str("Render job UUID")],["job_id"],read:true),
            tool(names[16], "Cancel a queued or running geometry render. A cancelled result cannot overwrite the lesson.",["job_id":str("Render job UUID")],["job_id"]),
            tool(names[17], "Apply a finished ready scene after the lesson changed during rendering. Uses its target lesson and requires that lesson's current revision.",["job_id":str("Render job UUID"),"expected_revision":rev],["job_id","expected_revision"]),
            tool(names[18], "Import a PNG/JPEG surface image. Returns a managed texture filename to use in a geometry scene. Normalizes to at most 2048 pixels per edge.",["image_base64":str("Base64 PNG/JPEG up to 15 MB decoded")],["image_base64"])
        ]
    }
}
